  rateLimit: "You have reached today's limit. Upgrade to Magic Wand+ for priority access.",
  bioSanitize: "Please use plain text only — no links or hashtags.",
  rejection: "We need a little more detail to get this right. Please update here: [Link]",
  t120patience: "High demand today — your kit will be ready shortly. Thank you for your patience 🧚 ",
  upsell: "Order confirmed! 📦 Want us to build your PageFairy brand setup while you wait? Reply MAGIC to add Magic Wand+ for $99.",
  soldOut: "This drop is sold out. Type NOTIFY to join the waitlist.",
  expiredLink: "That link has expired. Type REJOIN to request a new one.",
  selfReferral: "Referral not eligible — self-referrals don't count.",
  cashoutReceived: "Request received — review takes up to 48 hours. We'll notify you here when it's approved."
} }];
